/* htmx shim placeholder.
 *
 * For production use, drop a real htmx.min.js (and htmx SSE extension)
 * into this directory. The UI's progressive enhancement still works
 * without htmx: each page issues a single ``fetch`` and renders the
 * result into a list. htmx only adds the live tail / partial swap.
 *
 * The shim defines ``window.htmx`` so the script never 404s in tests.
 */
(function () {
  "use strict";
  if (typeof window !== "undefined" && !window.htmx) {
    window.htmx = {
      version: "0.0.0-shim",
      config: {},
      on: function () {},
      off: function () {},
      trigger: function () {},
    };
  }
})();
